public class GlobMatcherTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("star in the middle", true, GlobMatcher.matches("a*c", "abbbc"));
            check("star can match nothing", true, GlobMatcher.matches("a*c", "ac"));
            check("question mark needs a character", false, GlobMatcher.matches("a?c", "ac"));
            check("question mark matches one", true, GlobMatcher.matches("a?c", "abc"));
            check("suffix pattern", true, GlobMatcher.matches("*.txt", "notes.txt"));
            check("whole text must be consumed", false, GlobMatcher.matches("*.txt", "notes.txtx"));
            check("lone star matches empty", true, GlobMatcher.matches("*", ""));
            check("empty pattern rejects text", false, GlobMatcher.matches("", "x"));
            check("several stars", true, GlobMatcher.matches("*a*a*", "banana"));
            check("case is significant", false, GlobMatcher.matches("a*", "Abc"));
            check("filter keeps order", "[a.txt, notes.txt]",
                    GlobMatcher.filter(java.util.Arrays.asList("a.txt", "b.md", "notes.txt"), "*.txt").toString());
        } catch (Throwable t) {
            broke("matches", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

