import java.util.ArrayList;
import java.util.List;

public class GlobMatcher {

    public static boolean matches(String pattern, String text) {
        int n = pattern.length();
        int m = text.length();
        boolean[][] ok = new boolean[n + 1][m + 1];
        ok[0][0] = true;
        for (int i = 1; i <= n; i++) {
            ok[i][0] = ok[i - 1][0] && pattern.charAt(i - 1) == '*';
        }
        for (int i = 1; i <= n; i++) {
            char p = pattern.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (p == '*') {
                    ok[i][j] = ok[i - 1][j] || ok[i][j - 1];
                } else if (p == '?' || p == text.charAt(j - 1)) {
                    ok[i][j] = ok[i - 1][j - 1];
                }
            }
        }
        return ok[n][m];
    }

    public static List<String> filter(List<String> names, String pattern) {
        List<String> kept = new ArrayList<>();
        for (String name : names) {
            if (matches(pattern, name)) {
                kept.add(name);
            }
        }
        return kept;
    }
}
